    // Split the input string into month, day, and year components
    String[] parts = date.trim().split("\\s+");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    // Array of month names, 1-indexed (month 1 -> January, etc.)
    String[] monthNames = {
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String monthName = monthNames[month - 1];

    // Create a LocalDate object to determine the day of the week
    java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
    String dayName = localDate.getDayOfWeek()
                              .getDisplayName(java.time.format.TextStyle.FULL,
                                              java.util.Locale.ENGLISH);

    // Construct and return the formatted result
    return monthName + " " + day + ", " + year + " is a " + dayName;
}

