public String sortString(String s) {
    char[] arr = s.toCharArray();
    Arrays.sort(arr);
    int n = arr.length;
    boolean[] used = new boolean[n];
    StringBuilder sb = new StringBuilder();
    int unused = n;
    while (unused > 0) {
        // ascending: pick smallest > last appended (effectively next unused). We just iterate forward.
        for (int i = 0; i < n; i++) {
            if (!used[i]) {
                sb.append(arr[i]);
                used[i] = true;
                unused--;
            }
        }
        // descending
        for (int i = n-1; i >= 0; i--) {
            if (!used[i]) {
                sb.append(arr[i]);
                used[i] = true;
                unused--;
            }
        }
    }
    return sb.toString();
}

